class Solution {
    public double findMaxAverage(int[] nums, int k) {
        long windowSum = 0;
        for (int i = 0; i < k; i++) {
            windowSum += nums[i];
        }

        long bestSum = windowSum;
        for (int right = k; right < nums.length; right++) {
            windowSum += nums[right];
            windowSum -= nums[right - k];
            bestSum = Math.max(bestSum, windowSum);
        }

        return (double) bestSum / k;
    }
}

class Solution {
    public double findMaxAverage(int[] nums, int k) {
        long[] prefix = new long[nums.length + 1];
        for (int i = 0; i < nums.length; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
        }

        long bestSum = Long.MIN_VALUE;
        for (int right = k; right <= nums.length; right++) {
            long windowSum = prefix[right] - prefix[right - k];
            bestSum = Math.max(bestSum, windowSum);
        }

        return (double) bestSum / k;
    }
}

class Solution {
    public double findMaxAverage(int[] nums, int k) {
        double low = nums[0];
        double high = nums[0];
        for (int value : nums) {
            low = Math.min(low, value);
            high = Math.max(high, value);
        }

        for (int step = 0; step < 60; step++) {
            double mid = low + (high - low) / 2.0;
            if (hasWindowAtLeast(nums, k, mid)) {
                low = mid;
            } else {
                high = mid;
            }
        }
        return low;
    }

    private boolean hasWindowAtLeast(int[] nums, int k, double target) {
        double transformedSum = 0.0;
        for (int i = 0; i < k; i++) {
            transformedSum += nums[i] - target;
        }
        if (transformedSum >= 0.0) {
            return true;
        }

        for (int right = k; right < nums.length; right++) {
            transformedSum += nums[right] - target;
            transformedSum -= nums[right - k] - target;
            if (transformedSum >= 0.0) {
                return true;
            }
        }
        return false;
    }
}
